ALTER TABLE service CHANGE contract_term contract_term_old VARCHAR(100);
ALTER TABLE service ADD COLUMN contract_term int;
UPDATE service SET contract_term = 1 WHERE contract_term_old = 'MTM';
UPDATE service SET contract_term = 12 WHERE contract_term_old = '12 Month';
UPDATE service SET contract_term = 24 WHERE contract_term_old = '24 Month';
UPDATE service SET contract_term = 36 WHERE contract_term_old = '36 Month';
UPDATE service SET contract_term = 48 WHERE contract_term_old = '48 Month';
UPDATE service SET contract_term = 60 WHERE contract_term_old = '60 Month';

ALTER TABLE location_custom_field_value
  ADD CONSTRAINT PK_location_custom_field PRIMARY KEY (location_id, custom_field_value_id);

ALTER TABLE service_custom_field_value
  ADD CONSTRAINT PK_service_custom_field PRIMARY KEY (service_id, custom_field_value_id);

delete  from activation_attempt_requirement where requirement_id <= 26;
delete from requirement where requirement_id <= 26;
update location set requirement_template_id = null where requirement_template_id <= 5;
delete from requirement_template where requirement_template_id <= 5;
